import {
  applyCraftAction,
  createCraftSession,
  itemMatchesTargets,
  redoCraft,
  runCraftUntil,
  undoCraft,
  type CraftAction,
  type CraftSession,
  type CraftedItem
} from "@poe-odyssey/core";
import {
  Check,
  Clipboard,
  Coins,
  FlaskConical,
  History,
  Redo2,
  RotateCcw,
  Save,
  Sparkles,
  Undo2
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { PageTitle } from "../App";
import { craftActions, craftBases } from "../content/toolboxData";
import { saveCraft, savedCrafts } from "../storage";

const families: Array<{ id: CraftAction["family"] | "all"; zhTW: string; en: string }> = [
  { id: "all", zhTW: "全部", en: "All" },
  { id: "currency", zhTW: "通貨", en: "Currency" },
  { id: "essence", zhTW: "精髓", en: "Essence" },
  { id: "fossil", zhTW: "化石", en: "Fossil" },
  { id: "influence", zhTW: "勢力", en: "Influence" },
  { id: "harvest", zhTW: "花園", en: "Harvest" },
  { id: "eldritch", zhTW: "異能", en: "Eldritch" },
  { id: "betrayal", zhTW: "密教", en: "Betrayal" },
  { id: "bench", zhTW: "工藝台", en: "Bench" },
  { id: "recombinator", zhTW: "重組器", en: "Recombinator" }
];

function itemText(item: CraftedItem): string {
  const rarity = item.rarity === "rare" ? "Rare" : item.rarity === "magic" ? "Magic" : "Normal";
  return [
    `Rarity: ${rarity}`,
    item.name.en,
    "--------",
    `Item Level: ${item.itemLevel}`,
    `Quality: +${item.quality}%`,
    item.influence ? `Influence: ${item.influence}` : "",
    item.corrupted ? "Corrupted" : "",
    "--------",
    ...item.mods.map((mod) => `${mod.fractured ? "{fractured} " : mod.crafted ? "{crafted} " : ""}${mod.name.en} [${mod.value}]`)
  ].filter(Boolean).join("\n");
}

function ItemPanel({ item, label }: { item: CraftedItem; label?: string }) {
  const prefixes = item.mods.filter((mod) => mod.group === "prefix");
  const suffixes = item.mods.filter((mod) => mod.group === "suffix");
  const implicits = item.mods.filter((mod) => mod.group === "implicit");
  return (
    <div className={`crafted-item ${item.rarity}`}>
      {label && <span className="item-label">{label}</span>}
      <small>{item.rarity.toUpperCase()} · ITEM LEVEL {item.itemLevel}</small>
      <h2>{item.name.zhTW}</h2>
      <p>{item.name.en}</p>
      <div className="item-properties">
        <span>品質 +{item.quality}%</span>
        {item.influence && <span>{item.influence}</span>}
        {item.corrupted && <span className="corrupted">已汙染 / Corrupted</span>}
      </div>
      {implicits.length > 0 && <div className="implicit-mods">{implicits.map((mod) => <p key={mod.id}>{mod.name.zhTW} <b>{mod.value}</b></p>)}</div>}
      <div className="affix-section">
        <small>PREFIXES {prefixes.length}/3</small>
        {prefixes.length ? prefixes.map((mod) => (
          <p key={mod.id} className={`${mod.fractured ? "fractured" : ""} ${mod.crafted ? "crafted" : ""}`}>
            {mod.name.zhTW} <b>{mod.value}</b><small>{mod.name.en}</small>
          </p>
        )) : <em>沒有前綴 / No prefix</em>}
      </div>
      <div className="affix-section">
        <small>SUFFIXES {suffixes.length}/3</small>
        {suffixes.length ? suffixes.map((mod) => (
          <p key={mod.id} className={`${mod.fractured ? "fractured" : ""} ${mod.crafted ? "crafted" : ""}`}>
            {mod.name.zhTW} <b>{mod.value}</b><small>{mod.name.en}</small>
          </p>
        )) : <em>沒有後綴 / No suffix</em>}
      </div>
    </div>
  );
}

export function CraftPage() {
  const [baseId, setBaseId] = useState(craftBases[0]!.id);
  const base = craftBases.find((entry) => entry.id === baseId) ?? craftBases[0]!;
  const [session, setSession] = useState<CraftSession>(() => createCraftSession(base, 329));
  const [family, setFamily] = useState<(typeof families)[number]["id"]>("all");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [targetIds, setTargetIds] = useState<string[]>([]);
  const [maximumAttempts, setMaximumAttempts] = useState(50);
  const [saved, setSaved] = useState<CraftSession[]>([]);

  useEffect(() => {
    void savedCrafts().then(setSaved);
  }, []);

  useEffect(() => {
    void saveCraft(session);
  }, [session]);

  const compatibleActions = useMemo(() =>
    craftActions.filter((action) => {
      if (family !== "all" && action.family !== family) return false;
      if (action.guaranteedModId && !base.modPool.some((mod) => mod.id === action.guaranteedModId)) return false;
      if (action.effect === "influence" && !base.modPool.some((mod) => mod.source === "influence")) return false;
      if (action.effect === "eldritch" && !base.modPool.some((mod) => mod.source === "eldritch")) return false;
      if (action.effect === "betrayal" && !base.modPool.some((mod) => mod.source === "betrayal")) return false;
      return true;
    }),
  [base, family]);

  function selectBase(nextId: string) {
    const nextBase = craftBases.find((entry) => entry.id === nextId) ?? craftBases[0]!;
    setBaseId(nextId);
    setSession(createCraftSession(nextBase, 329));
    setTargetIds([]);
    setError("");
    setNotice("已建立乾淨底材。");
  }

  function apply(action: CraftAction) {
    try {
      setSession(applyCraftAction(session, base, action));
      setError("");
      setNotice(`${action.name.zhTW}完成。`);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "操作無法套用");
    }
  }

  function createDonor() {
    try {
      const donorSession = applyCraftAction(
        createCraftSession(base, (session.seed + 997) >>> 0),
        base,
        craftActions.find((entry) => entry.effect === "alchemy")!
      );
      const next = { ...session, donor: donorSession.current, updatedAt: new Date().toISOString() };
      setSession(next);
      setNotice("已產生同底材的稀有供體；可測試重組器。");
      setError("");
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "供體建立失敗");
    }
  }

  function autoRun(action: CraftAction) {
    if (!targetIds.length) {
      setError("請先選擇至少一個目標詞綴。");
      return;
    }
    try {
      const result = runCraftUntil(session, base, action, targetIds, maximumAttempts);
      setSession(result.session);
      setNotice(`${result.attempts} 次後${result.matched ? "達成目標" : "仍未達成目標"}。`);
      setError("");
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "自動重試停止");
    }
  }

  const autoActions = compatibleActions.filter((action) =>
    ["alteration", "chaos", "fossil", "harvest", "essence"].includes(action.effect)
  );

  return (
    <div className="page craft-page">
      <PageTitle
        eyebrow="DETERMINISTIC CRAFTING LAB · 3.29"
        title="先在這裡燒通貨"
        description="可重現亂數的離線做裝實驗室：通貨、精髓、化石、勢力、花園、異能、密教、工藝台、破裂與重組器。"
      >
        <button className="button secondary" onClick={() => void navigator.clipboard.writeText(itemText(session.current))}><Clipboard size={15} /> 複製物品</button>
      </PageTitle>

      <section className="craft-setup panel">
        <label>
          <span>底材 / Base</span>
          <select value={baseId} onChange={(event) => selectBase(event.target.value)}>
            {craftBases.map((entry) => <option key={entry.id} value={entry.id}>{entry.name.zhTW} / {entry.name.en}</option>)}
          </select>
        </label>
        <div><small>需求</small><strong>{base.requirements}</strong></div>
        <div><small>資料版本</small><strong>3.29.0</strong></div>
        <div><small>可重現 Seed</small><strong>{session.seed}</strong></div>
        <button className="button secondary" onClick={() => selectBase(baseId)}><RotateCcw size={15} /> 乾淨底材</button>
      </section>

      {(error || notice) && <div className={`inline-message ${error ? "error" : ""}`}>{error || notice}</div>}

      <section className="craft-workspace">
        <div className="item-column">
          <ItemPanel item={session.current} label="目標物品 / TARGET" />
          {session.donor ? <ItemPanel item={session.donor} label="重組供體 / DONOR" /> : (
            <button className="donor-placeholder" onClick={createDonor}><Sparkles size={21} /> 建立稀有供體，測試重組器</button>
          )}
        </div>

        <div className="craft-controls panel">
          <div className="craft-family-tabs">
            {families.map((entry) => (
              <button key={entry.id} className={family === entry.id ? "active" : ""} onClick={() => setFamily(entry.id)}>
                {entry.zhTW}<small>{entry.en}</small>
              </button>
            ))}
          </div>
          <div className="craft-action-grid">
            {compatibleActions.map((entry) => (
              <button key={entry.id} onClick={() => apply(entry)}>
                <FlaskConical size={17} />
                <span>{entry.name.zhTW}<small>{entry.name.en}</small></span>
                <b>{entry.cost}×</b>
              </button>
            ))}
          </div>

          <div className="craft-history-actions">
            <button className="button secondary" disabled={!session.history.length} onClick={() => setSession(undoCraft(session))}><Undo2 size={15} /> 復原</button>
            <button className="button secondary" disabled={!session.future.length} onClick={() => setSession(redoCraft(session))}><Redo2 size={15} /> 重做</button>
            <button className="button secondary" onClick={() => { void saveCraft(session); setNotice("工作階段已存入 IndexedDB。"); }}><Save size={15} /> 保存</button>
          </div>
        </div>
      </section>

      <section className="craft-lower-grid">
        <article className="panel craft-targets">
          <div className="panel-title"><Check size={18} /><div><h3>目標條件與自動重試</h3><small>AUTO-ROLL UNTIL</small></div></div>
          <div className="target-mod-list">
            {base.modPool.filter((entry) => entry.group !== "implicit" && entry.source !== "bench").map((entry) => (
              <label key={entry.id}>
                <input
                  type="checkbox"
                  checked={targetIds.includes(entry.id)}
                  onChange={() => setTargetIds(targetIds.includes(entry.id) ? targetIds.filter((id) => id !== entry.id) : [...targetIds, entry.id])}
                />
                <span>{entry.name.zhTW}<small>{entry.name.en}</small></span>
              </label>
            ))}
          </div>
          <div className="auto-roll-controls">
            <label>最多次數 <input type="number" min={1} max={500} value={maximumAttempts} onChange={(event) => setMaximumAttempts(Math.max(1, Math.min(500, Number(event.target.value))))} /></label>
            {autoActions.map((entry) => <button className="button secondary" key={entry.id} onClick={() => autoRun(entry)}>{entry.name.zhTW}</button>)}
          </div>
          <p className="target-status">{itemMatchesTargets(session.current, targetIds) && targetIds.length ? "目前物品已達成所有目標。" : "選擇詞綴後，以可重鑄操作自動嘗試；最多 500 次。"}</p>
        </article>

        <article className="panel craft-ledger">
          <div className="panel-title"><Coins size={18} /><div><h3>花費與歷史</h3><small>COST LEDGER</small></div></div>
          <div className="cost-list">
            {Object.entries(session.costs).filter(([, amount]) => amount > 0).map(([id, amount]) => <span key={id}>{id}<strong>{amount}</strong></span>)}
            {!Object.values(session.costs).some((amount) => amount > 0) && <p>尚未花費通貨。</p>}
          </div>
          <ol className="history-list">
            {session.history.slice(-8).reverse().map((entry, index) => (
              <li key={`${entry.actionId}-${session.history.length - index}`}><History size={13} /><span>{entry.actionId}</span><b>{entry.cost} {entry.costCurrencyId}</b></li>
            ))}
          </ol>
          {saved.length > 0 && (
            <label className="restore-craft">
              <span>載入先前工作階段</span>
              <select value="" onChange={(event) => {
                const selected = saved.find((entry) => entry.id === event.target.value);
                if (selected) { setBaseId(selected.current.baseId); setSession(selected); }
              }}>
                <option value="">選擇…</option>
                {saved.map((entry) => <option key={entry.id} value={entry.id}>{entry.current.name.zhTW} · {new Date(entry.updatedAt).toLocaleString("zh-TW")}</option>)}
              </select>
            </label>
          )}
        </article>
      </section>
      <p className="source-footnote">模擬器用於比較製作流程，不取代遊戲伺服器。詞綴池鎖定 PoeOdyssey 3.29.0 精選底材；實際投入高價通貨前請再以遊戲內說明與 Craft of Exile 類工具交叉確認。</p>
    </div>
  );
}
